function calculate(id,raw){const c=calculators.find(c=>c.id===Number(id));if(!c)throw Error('Unknown calculator.');const v={...raw};for(const field of c.fields){if(field.when&&!field.when(v))continue;const x=v[field.key];if(x===undefined||x===null||String(x).trim()==='')throw Error(`Enter ${field.label}`);if(field.type==='number'){const n=Number(x);if(!Number.isFinite(n)||n<field.min||n>field.max)throw Error(`${field.label}: enter a finite value from ${field.min} to ${field.max}.`);v[field.key]=n;}else{if(!field.options.some(o=>o[0]===String(x)))throw Error(`Select a valid ${field.label}`);v[field.key]=String(x);}}const result=c.compute(v);if(result.value!==null&&!Number.isFinite(result.value))throw Error('Unable to calculate a finite result. Check the inputs.');return result;}
const api={calculators,calculate};if(typeof module==='object'&&module.exports)module.exports=api;root.ClinicalCalculators=api;
if(typeof document==='undefined')return;
function element(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;}
function renderCard(c){const card=element('article','calc-card');card.dataset.calculatorId=c.id;const header=element('div','calc-card-heading');header.append(element('span','calc-index',String(c.id).padStart(2,'0')),element('span','calc-category',c.group));card.append(header,element('h4','',c.title));const form=element('form','calc-form');const inputs={};const result=element('output','calc-result','Enter all fields, then calculate.');result.setAttribute('aria-live','polite');result.id=`calculator-result-${c.id}`;const raw=()=>Object.fromEntries(Object.entries(inputs).map(([k,x])=>[k,x.value]));
for(const field of c.fields){const wrap=element('label','calc-field');wrap.append(element('span','',field.label));const input=element(field.type==='select'?'select':'input');input.id=`calculator-${c.id}-${field.key}`;input.name=field.key;input.setAttribute('aria-label',field.label);input.autocomplete='off';if(field.type==='select'){const blank=element('option','','Select…');blank.value='';input.append(blank);for(const [value,label]of field.options){const o=element('option','',label);o.value=value;input.append(o);}}else{input.type='number';input.step='any';input.min=field.min;if(Number.isFinite(field.max))input.max=field.max;}input.required=true;wrap.append(input);form.append(wrap);inputs[field.key]=input;
input.addEventListener('input',()=>{result.textContent='Inputs changed — calculate again.';result.classList.remove('error');sync();});}
function sync(){const v=raw();for(const field of c.fields){const show=!field.when||field.when(v);inputs[field.key].parentElement.hidden=!show;inputs[field.key].disabled=!show;inputs[field.key].required=show;}}sync();
const controls=element('div','calc-actions');const button=element('button','calc-primary','Calculate');button.type='submit';const reset=element('button','','Clear');reset.type='reset';controls.append(button,reset);form.append(controls,result);form.addEventListener('submit',e=>{e.preventDefault();try{result.textContent=calculate(c.id,raw()).text;result.classList.remove('error');}catch(err){result.textContent=err.message;result.classList.add('error');}});form.addEventListener('reset',()=>{setTimeout(()=>{sync();result.textContent='Enter all fields, then calculate.';result.classList.remove('error');},0);});card.append(form);const reference=element('div','calc-reference-note');reference.append(element('strong','','Standard reference range / threshold / interpretation'));reference.append(element('p','',c.note));reference.append(element('p','calc-reference-disclaimer','Reference values are typical published guidance, not a universal laboratory interval or a patient-specific treatment target. Local laboratory ranges and clinical titration protocols may differ; verify the reporting laboratory and current clinician-approved guidance. This calculator does not prescribe or titrate treatment.'));const source=element('a','calc-reference-link','Open clinical source ↗');source.href=c.url;source.target='_blank';source.rel='noopener noreferrer';reference.append(source);if(c.interpretationUrl){const extra=element('a','calc-reference-link','HbA1c diagnostic thresholds ↗');extra.href=c.interpretationUrl;extra.target='_blank';extra.rel='noopener noreferrer';reference.append(extra);}card.append(reference);const details=element('details','calc-evidence');details.append(element('summary','','Formula & methodology'),element('p','calc-formula',c.formula));card.append(details);return card;}
api.render=function(){const publicGrid=document.getElementById('calc30Grid');const clinicalGrid=document.getElementById('clinicalCalculatorGrid');if(!publicGrid||!clinicalGrid)return;publicGrid.replaceChildren();clinicalGrid.replaceChildren();for(const c of calculators)(c.group==='Public'?publicGrid:clinicalGrid).append(renderCard(c));const search=document.getElementById('clinicalCalculatorSearch');if(search)search.oninput=()=>clinicalGrid.querySelectorAll('.calc-card').forEach(card=>{card.hidden=!card.textContent.toLowerCase().includes(search.value.toLowerCase());});};
